with targets as materialized (select id,notes from public.companies where notes like '%[GMAIL_MEGKERESES_2026-11-06]%' and not exists (select 1 from public.contacts ct join public.emails e on exists(select 1 from unnest(coalesce(e.to_emails,'{}')||coalesce(e.cc_emails,'{}')||coalesce(e.bcc_emails,'{}')) a where lower(trim(a))=lower(trim(ct.email))) join public.users_profile p on p.auth_user_id=e.owner_user_id where ct.company_id=companies.id and split_part(lower(trim(ct.email)),'@',2)<>'vibateam.hu' and lower(trim(ct.email)) not in ('viktor.csotai@gmail.com','info@nexohabit.com') and lower(trim(p.gmail_email)) in ('info@vibateam.hu','ramon.dencsi@vibateam.hu','pretor.laszlo@vibateam.hu') and lower(trim(e.from_email))=lower(trim(p.gmail_email)) and e.is_outbound=true and e.gmail_label_ids @> array['SENT']::text[] and not e.gmail_label_ids @> array['DRAFT']::text[] and e.gmail_message_id is not null and e.internal_date is not null)), guard as (select count(*)=121 and md5(string_agg(id::text||notes,'' order by id))='16e12ca2be8450641c1520e2773422e7' as ok from targets), changed as (update public.companies c set notes=regexp_replace(c.notes, '\[GMAIL_MEGKERESES_2026-11-06\]\nKapcsolati csoport: Megkeresett cég\nÁllapot: Megkeresett \(hideg e-mail kiment\)\nElső megkeresés: [^\n]+\nUtolsó kiküldés: [^\n]+\nKüldő postafiók: [^\n]+\nCímzett: [^\n]+', '[GMAIL_ELLENORZES_2026-11-06]'||chr(10)||'Küldési bizonyíték: '||case when c.id='057b657a-aded-4193-aa07-139948c85de9' then 'Belső/TESZT-levél; nem külső üzleti megkeresés.' else 'Csak tárolt piszkozat; külső Gmail SENT-küldés nem igazolt.' end||chr(10)||'A korábbi megkeresésjelölés javítva; a történeti lefedettség nem teljes.'||chr(10)||'Ellenőrzés: 2026-11-06; három céges postafiók tárolt adata.') from targets t,guard g where c.id=t.id and c.notes=t.notes and g.ok returning c.id) select count(*) as corrected from changed;